INSERT INTO glossary(pos,doc) VALUES (0,'["Quá hạn","Việc <b>đang mở</b> và đã qua hạn cam kết. Là <b>trạng thái hôm nay</b>, còn sửa được.","quaHan(t)","Việc của tôi · Điều hành · Theo dõi · Cá nhân"]'::jsonb);
INSERT INTO glossary(pos,doc) VALUES (1,'["Trễ","Việc <b>đến hạn trong kỳ</b> mà không về đích đúng hạn — gồm cả việc đã xong nhưng nộp muộn. Là <b>kết quả của kỳ</b>, đã chốt.","treTruoc trong soLieuKy()","Giao ban · Đã xong"]'::jsonb);
INSERT INTO glossary(pos,doc) VALUES (2,'["Việc đang mở","Việc chưa được nghiệm thu xong. Không tính việc đã đóng.","viecMo(t)","Mọi cửa sổ"]'::jsonb);
INSERT INTO glossary(pos,doc) VALUES (3,'["Cần can thiệp","Việc đang mở có ít nhất một cảnh báo nguy cơ — <b>chưa chắc đã quá hạn</b>.","canCanThiep(t)","Điều hành · Theo dõi · Dự án"]'::jsonb);
INSERT INTO glossary(pos,doc) VALUES (4,'["Đang tắc","Việc đang mở nhưng dừng lại chờ người khác: chờ nghiệm thu, chờ trả lời ý kiến, hoặc bị trả lại.","yKien / CHO_DUYET / TRA_LAI","Giao ban · Cá nhân"]'::jsonb);
INSERT INTO glossary(pos,doc) VALUES (5,'["Dừng đồng hồ","Việc quá hạn nhưng <b>không tính là quá hạn</b> vì đang chờ bên ngoài: có ý kiến chưa trả lời, hoặc ở trạng thái riêng loại chờ ngoài.","dangDung(t)","Phiếu việc · mọi phép đếm quá hạn"]'::jsonb);
INSERT INTO glossary(pos,doc) VALUES (6,'["Quá tải","Tổng điểm độ khó của việc đang mở trong tuần vượt sức một tuần.","taiTuanNay(id) > SUC_TUAN","Điều hành · Cá nhân · Giao ban"]'::jsonb);
