INSERT INTO external_event(ma,pos,doc) VALUES ('TN01',0,'{"ma":"TN01","nhom":"CHINH_SACH","ten":"Nghị định 273/2026/NĐ-CP về kinh doanh hàng miễn thuế","so":"273/2026/NĐ-CP","hieuLuc":"21/08/2026","nd":"Người mua không phải xuất trình giấy tờ nếu thông tin đã được chia sẻ từ cơ sở dữ liệu.","nguon":"Cổng Thông tin điện tử Chính phủ","url":"https://baochinhphu.vn/chinh-sach-moi-co-hieu-luc-tu-thang-8-2026-102260731143849894.htm","ngay":"31/07/2026","ah":"VUA","xacNhan":false,"viSao":"Công ty có hoạt động xuất nhập khẩu; thay đổi thủ tục chứng từ ở khâu hàng miễn thuế có thể kéo theo thay đổi hồ sơ lưu và cách đối chiếu của Tổ Xuất nhập khẩu.","lam":"Pháp chế đọc toàn văn, xác định có áp dụng cho mặt hàng của công ty không; nếu có thì cập nhật quy trình hồ sơ trước ngày hiệu lực.","dv":"PC","han":"18/08/2026"}'::jsonb);
INSERT INTO external_event(ma,pos,doc) VALUES ('TN02',1,'{"ma":"TN02","nhom":"CHINH_SACH","ten":"Nghị định 274/2026/NĐ-CP — ưu đãi cho đầu tư công nghệ cao, công nghệ xanh","so":"274/2026/NĐ-CP","hieuLuc":"21/08/2026","nd":"Ưu đãi tài chính 5% cho nhà đầu tư ứng dụng công nghệ cao hoặc công nghệ xanh; chuẩn hoá chi phí lập hồ sơ đấu thầu tối đa 200 triệu đồng.","nguon":"Cổng Thông tin điện tử Chính phủ","url":"https://baochinhphu.vn/chinh-sach-moi-co-hieu-luc-tu-thang-8-2026-102260731143849894.htm","ngay":"31/07/2026","ah":"VUA","xacNhan":false,"viSao":"Nếu công ty có kế hoạch đầu tư kho, thiết bị hoặc phần mềm trong 12 tháng tới thì đây là khoản ưu đãi bỏ qua thì mất.","lam":"Tài chính rà danh mục đầu tư dự kiến, đối chiếu điều kiện hưởng ưu đãi, báo Ban Giám đốc trong cuộc họp tháng.","dv":"TCKT","han":"15/09/2026"}'::jsonb);
INSERT INTO external_event(ma,pos,doc) VALUES ('TN03',2,'{"ma":"TN03","nhom":"CHINH_SACH","ten":"Thông tư 31/2026/TT-NHNN — cho thuê tài chính với phần mềm và dữ liệu","so":"31/2026/TT-NHNN","hieuLuc":"15/08/2026","nd":"Đưa phần mềm và dữ liệu vào danh mục tài sản được cho thuê tài chính.","nguon":"Cổng Thông tin điện tử Chính phủ","url":"https://baochinhphu.vn/chinh-sach-moi-co-hieu-luc-tu-thang-8-2026-102260731143849894.htm","ngay":"31/07/2026","ah":"THAP","xacNhan":false,"viSao":"Mở thêm một cách tài trợ cho chính khoản đầu tư phần mềm quản lý công việc đang triển khai — chuyển từ chi một lần sang thuê.","lam":"Tài chính hỏi thử hai đơn vị cho thuê, so với phương án mua đứt.","dv":"TCKT","han":"30/09/2026"}'::jsonb);
INSERT INTO external_event(ma,pos,doc) VALUES ('TN04',3,'{"ma":"TN04","nhom":"CHINH_SACH","ten":"Nghị định 281/2026/NĐ-CP — nâng mức phạt vi phạm đất đai","so":"281/2026/NĐ-CP","hieuLuc":"31/08/2026","nd":"Nâng mức phạt tối đa lên 250–400 triệu đồng.","nguon":"Cổng Thông tin điện tử Chính phủ","url":"https://baochinhphu.vn/chinh-sach-moi-co-hieu-luc-tu-thang-8-2026-102260731143849894.htm","ngay":"31/07/2026","ah":"THEO_DOI","xacNhan":false,"viSao":"Chỉ chạm tới công ty nếu có mặt bằng kho thuê hoặc sở hữu đang có vướng mắc hồ sơ đất.","lam":"Pháp chế xác nhận tình trạng hồ sơ mặt bằng kho; nếu sạch thì đóng dòng này lại.","dv":"PC","han":"25/08/2026"}'::jsonb);
INSERT INTO external_event(ma,pos,doc) VALUES ('TN05',4,'{"ma":"TN05","nhom":"THI_TRUONG","ten":"Kim ngạch xuất nhập khẩu cả nước tăng 28,1%","so":null,"hieuLuc":null,"nd":"7 tháng đầu 2026 đạt 659,58 tỷ USD. Xuất khẩu +21,7%, nhập khẩu +34,8%, nhập siêu 20,52 tỷ USD.","nguon":"Tổng cục Thống kê, dẫn qua VietnamPlus","url":"https://www.vietnamplus.vn/7-thang-nam-2026-tong-kim-ngach-xuat-nhap-khau-hang-hoa-tang-281-post1128008.vnp","ngay":"04/08/2026","ah":"CAO","xacNhan":true,"viSao":"Ngành đang mở rộng nhanh. Khối lượng việc của công ty tăng theo là bình thường — nhưng tồn kho việc đang mở cũng tăng theo, và đó mới là chỗ phải xử.","lam":"Khi giao kế hoạch kỳ tới, tính thêm phần tăng theo thị trường thay vì giữ nguyên mức cũ rồi để phát sinh đột xuất chen ngang.","dv":"ADKD","han":null}'::jsonb);
INSERT INTO external_event(ma,pos,doc) VALUES ('TN06',5,'{"ma":"TN06","nhom":"THI_TRUONG","ten":"PMI sản xuất Việt Nam 51,8 — còn mở rộng nhưng chậm lại","so":null,"hieuLuc":null,"nd":"Tháng 6/2026 đạt 51,8, giảm từ 52,8. Đơn hàng mới còn tăng, doanh nghiệp vẫn cắt giảm nhân sự, chuỗi cung ứng còn chậm giao.","nguon":"S&P Global, dẫn qua VietnamPlus","url":"https://en.vietnamplus.vn/manufacturing-sector-ends-first-half-of-2026-with-firm-growth-as-pmi-holds-above-no-change-mark-post347589.vnp","ngay":"01/07/2026","ah":"VUA","xacNhan":true,"viSao":"Chuỗi cung ứng chậm giao là sức ép tiến độ đến từ BÊN NGOÀI. Một phần việc trễ của công ty không phải lỗi nội bộ — nhưng phải chứng minh được bằng trạng thái riêng “chờ đối tác”, không phải bằng lời.","lam":"Bắt buộc dùng trạng thái riêng “chờ đối tác” cho việc đang chờ bên ngoài, để đồng hồ dừng đúng chỗ và báo cáo trễ không đổ oan cho người làm.","dv":"XNK","han":null}'::jsonb);
INSERT INTO external_event(ma,pos,doc) VALUES ('TN07',6,'{"ma":"TN07","nhom":"NGANH","ten":"Tỷ giá USD/VND và giá cước vận tải biển","so":null,"hieuLuc":null,"nd":"CHƯA NỐI NGUỒN. Cần nối tỷ giá trung tâm của Ngân hàng Nhà nước và một chỉ số cước container.","nguon":null,"url":null,"ngay":null,"ah":"CAO","xacNhan":false,"viSao":"Hai biến này chạm thẳng vào giá vốn của công ty xuất nhập khẩu — nhưng phần mềm chưa có số nên chưa nói được gì.","lam":"CNTT nối nguồn tỷ giá và chỉ số cước ở giai đoạn 2. Trước khi nối xong, KHÔNG dùng dòng này để kết luận.","dv":"TH","han":null}'::jsonb);
INSERT INTO benchmark(ma,pos,doc) VALUES ('DUNG_HAN',0,'{"ma":"DUNG_HAN","ten":"Tỷ lệ hoàn thành đúng hạn","donVi":"%","chieu":"cao_tot","moc":85,"dai":[80,90],"loai":"TU_DAT","nguon":"Mức công ty tự đặt trong tham số hệ thống","ngay":"01/01/2026","y":"Đây là CAM KẾT của công ty, không phải chuẩn ngành. Muốn so với ngành thì phải mua một khảo sát thật rồi thay dòng này."}'::jsonb);
INSERT INTO benchmark(ma,pos,doc) VALUES ('CHO_DUYET',1,'{"ma":"CHO_DUYET","ten":"Thời gian phiếu nằm chờ ở khâu duyệt","donVi":"giờ","chieu":"thap_tot","moc":8,"dai":[4,8],"loai":"TU_DAT","nguon":"Một ngày công — mức công ty tự đặt","ngay":"01/01/2026","y":"Quá một ngày công thì nút thắt nằm ở người duyệt, không ở người làm. Mốc này suy từ lịch làm việc của chính công ty nên kiểm chứng được."}'::jsonb);
INSERT INTO benchmark(ma,pos,doc) VALUES ('TRA_LAI',2,'{"ma":"TRA_LAI","ten":"Tỷ lệ việc bị trả lại khi nghiệm thu","donVi":"%","chieu":"thap_tot","moc":20,"dai":[10,20],"loai":"TU_DAT","nguon":"Ngưỡng cảnh báo trong tham số hệ thống","ngay":"01/01/2026","y":"Trả lại nhiều gần như luôn là tiêu chí nghiệm thu chưa rõ từ lúc giao, không phải người làm kém."}'::jsonb);
